def apply_neon_palette(apps, schema_editor):
    """Re-skin the existing singleton theme row (if any) to the new cyan / black / yellow / magenta palette."""
    ThemeSettings = apps.get_model("site_settings", "ThemeSettings")
    for row in ThemeSettings.objects.all():
        for key, value in PALETTE.items():
            setattr(row, key, value)
        row.save()


